package sarif

import (
	"compress/gzip"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/github/turboscan/ts"
	"github.com/github/turboscan/ts/proto"
	v2_1_0_turboscan "github.com/github/turboscan/ts/sarif/v2_1_0_turboscan"
	"github.com/mailru/easyjson"

	"github.com/pkg/errors"
)

type DecodingError struct {
	error
}

func (e DecodingError) Error() string {
	// easyjson will include JSON fragments in its error messages
	// if these contain NULL characters they cannot be saved by MySQL
	// replace any unprintable characters using strconv.Quote and then strip off the quotes
	msg := strconv.Quote(e.error.Error())
	return msg[1 : len(msg)-1]
}

// Decode reads JSON from reader into a fresh SARIF struct.
func Decode(data []byte) (*v2_1_0_turboscan.SARIF, error) {
	var out v2_1_0_turboscan.SARIF
	return &out, Unmarshal(data, &out)
}

func Unmarshal(data []byte, out *v2_1_0_turboscan.SARIF) error {
	// Parse a restricted subset of the SARIF.
	if err := easyjson.Unmarshal(data, out); err != nil {
		return errors.Wrap(DecodingError{err}, "parsing restricted subset of SARIF data has failed")
	}
	out.Normalise()
	if err := out.Validate(); err != nil {
		return errors.Wrap(DecodingError{err}, "validating restricted subset of SARIF data has failed")
	}
	return nil
}

// FromFile reads a SARIF from a JSON file
func FromFile(filePath string) (*v2_1_0_turboscan.SARIF, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, errors.Wrapf(err, "opening SARIF file %q has failed", filePath)
	}
	defer f.Close()

	var bytes []byte
	if strings.HasSuffix(filePath, ".gz") {
		var gzipReader *gzip.Reader
		gzipReader, err = gzip.NewReader(f)
		if err != nil {
			return nil, err
		}
		defer gzipReader.Close()
		bytes, err = io.ReadAll(gzipReader)
	} else {
		bytes, err = io.ReadAll(f)
	}
	if err != nil {
		return nil, errors.Wrap(err, "reading SARIF file into buffer has failed")
	}

	return Decode(bytes)
}

// ResultsByAlertNumber returns a map of the SARIF results based on their corresponding LogicalAlert number.
// This will only work for the processed SARIFs generated by turboscan.
func ResultsByAlertNumber(sarif *v2_1_0_turboscan.SARIF) (map[uint32]*v2_1_0_turboscan.Result, error) {
	resultMap := make(map[uint32]*v2_1_0_turboscan.Result)
	for _, run := range sarif.Runs {
		if run.Results == nil {
			continue
		}
		for _, result := range run.Results {
			if result.Properties != nil && result.Properties.GithubAlertNumber != 0 {
				resultMap[uint32(result.Properties.GithubAlertNumber)] = result
			}
		}
	}
	return resultMap, nil
}

// ResultsByLocations returns a list of the SARIF results that intersect with the provided file changes
func ResultsByLocations(sarif *v2_1_0_turboscan.SARIF, fileChangesMap map[string][]*proto.Change) []*v2_1_0_turboscan.Result {
	results := []*v2_1_0_turboscan.Result{}
	for _, run := range sarif.Runs {
		if run.Results == nil {
			continue
		}
		for _, result := range run.Results {
			if len(result.Locations) > 0 {
				if locationIntersectsChanges(result.Locations[0], fileChangesMap) {
					results = append(results, result)
					continue
				}
			}
			for _, location := range result.RelatedLocations {
				if locationIntersectsChanges(location, fileChangesMap) {
					results = append(results, result)
					continue
				}
			}
		}
	}
	return results
}

func locationIntersectsChanges(location *v2_1_0_turboscan.Location, fileChangesMap map[string][]*proto.Change) bool {
	if location.PhysicalLocation == nil {
		return false
	}
	loc := location.PhysicalLocation
	if loc.ArtifactLocation == nil || loc.ArtifactLocation.Uri == "" {
		return false
	}
	filePath, err := URIToPath(loc.ArtifactLocation.Uri, ts.EmptyCheckoutURI)
	if err != nil || filePath == "" {
		return false
	}
	if _, ok := fileChangesMap[filePath]; !ok {
		return false
	}
	for _, c := range fileChangesMap[filePath] {
		if loc.Region != nil && int(c.StartLine) <= loc.Region.StartLine && loc.Region.StartLine <= int(c.EndLine) {
			return true
		}
	}
	return false
}
